import React from 'react';

import { Heading } from '@hexa-ui/components';
import { Icon } from '@hexa-ui/components2';
import { Info } from '@hexa-ui/icons2';
import { BreadcrumbChips, CustomTooltip } from 'components';
import { useDrillDownBreadcrumb } from 'pages/pillars/ValueCreation/hooks/useDrillDownBreadcrumb';
import {
  StyledMainContainer,
  StyledMeasure,
  StyledTooltip,
} from 'shared/Styles';

import { COMMERCIAL_RESULTS_BREADCRUMB_CONFIG } from '../../constants/breadcrumbConfig';
import {
  StyledContentCardHeader,
  StyledContentCardHeaderTopRow,
  StyledTitleTooltipContainer,
} from './ContentCardWithBreadcrumb.styles';

export interface ContentCardWithBreadcrumbProps {
  readonly title: string;
  readonly measure?: string;
  readonly tooltip?: string;
  readonly children: React.ReactNode;
  readonly dataTestId?: string;
  readonly breadcrumb?: React.ReactNode;
  readonly rightContent?: React.ReactNode;
  readonly stickyHeader?: boolean;
  readonly stickyTopOffset?: string;
}

export function ContentCardWithBreadcrumb({
  title,
  measure,
  tooltip,
  children,
  dataTestId,
  breadcrumb,
  rightContent,
  stickyHeader = false,
  stickyTopOffset,
}: ContentCardWithBreadcrumbProps) {
  const { rootLabel, path, goToStep, isLoading } = useDrillDownBreadcrumb(
    COMMERCIAL_RESULTS_BREADCRUMB_CONFIG,
  );

  const testId = (suffix: string) =>
    dataTestId ? `${dataTestId}-${suffix}` : undefined;

  return (
    <StyledMainContainer fullWidth data-testid={dataTestId}>
      <StyledContentCardHeader
        data-testid={testId('header')}
        data-role="content-card-header"
        stickyHeader={stickyHeader}
        stickyTopOffset={stickyTopOffset}
      >
        <StyledContentCardHeaderTopRow>
          <StyledTitleTooltipContainer>
            <Heading size="H2" data-testid={testId('title')}>
              {title}
            </Heading>

            {measure && (
              <StyledMeasure
                size="small"
                color="gray"
                weight="light"
                data-testid={testId('measure')}
              >
                {measure}
              </StyledMeasure>
            )}

            {tooltip && (
              <CustomTooltip
                data-testid={testId('tooltip')}
                content={<StyledTooltip size="small">{tooltip}</StyledTooltip>}
              >
                <Icon icon={Info} size="medium" />
              </CustomTooltip>
            )}
          </StyledTitleTooltipContainer>

          {rightContent && (
            <div data-testid={testId('right-content')}>{rightContent}</div>
          )}
        </StyledContentCardHeaderTopRow>

        {breadcrumb ? (
          <span data-testid={testId('breadcrumb')}>{breadcrumb}</span>
        ) : (
          <BreadcrumbChips
            path={path}
            rootLabel={rootLabel}
            onGoToStep={goToStep}
            isLoading={isLoading}
            dataTestId={testId('breadcrumb')}
          />
        )}
      </StyledContentCardHeader>

      {children}
    </StyledMainContainer>
  );
}
